import { readFileSync, writeFileSync } from "node:fs";

const fontPath = new URL(import.meta.resolve("@fontsource/allura/files/allura-latin-400-normal.woff2"));
const outputPath = new URL("../src/lib/signatureFont.generated.ts", import.meta.url);
const chunks = readFileSync(fontPath).toString("base64").match(/.{1,120}/g) ?? [];
const source = [
  "// Generated by scripts/embed-signature-font.mjs. Do not edit by hand.",
  "export const signatureFontData = [",
  ...chunks.map((chunk) => `  "${chunk}",`),
  "].join(\"\");",
  ""
].join("\n");

writeFileSync(outputPath, source);
